{
  "case_id": "C07",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The problem",
      "narration": "About a third of people with major depression don't get better on the first antidepressant they try. Doctors would love a simple test that flags this in advance.",
      "on_screen": "Title card: 'Can a blood test predict antidepressant response?' Simple icon of a pill bottle and a blood tube.",
      "claim_refs": [
        "Background: roughly one third of patients with MDD do not respond to a first-line SSRI"
      ]
    },
    {
      "beat": "What was measured",
      "narration": "Researchers followed 512 adults starting an SSRI. Before treatment, they measured interleukin-6, or IL-6, a marker of inflammation in the blood, then checked depression scores twelve weeks later.",
      "on_screen": "512 person icons; timeline from 'Week 0: IL-6 blood test' to 'Week 12: depression score'.",
      "claim_refs": [
        "Abstract: cohort of 512 adults with MDD",
        "Methods: IL-6 measured once at baseline; response = 50% reduction in HAM-D at 12 weeks"
      ]
    },
    {
      "beat": "The finding",
      "narration": "People with the highest IL-6 levels responded far less often: thirty-four percent, compared with fifty-eight percent in the lowest group. That gap held after accounting for age, sex, weight and smoking.",
      "on_screen": "Two bars: 34% (high IL-6) vs 58% (low IL-6). Caption: 'adjusted odds ratio 0.41 (95% CI 0.27-0.63)'.",
      "claim_refs": [
        "Results: 34% vs 58% response at 12 weeks",
        "Results: adjusted OR 0.41 (0.27-0.63)",
        "Statistical analysis: adjusted for age, sex, baseline HAM-D, BMI, smoking"
      ]
    },
    {
      "beat": "The proposed explanation",
      "narration": "Why? The authors suggest inflammation diverts tryptophan, the raw material for serotonin, down a different chemical route, leaving less serotonin for the brain. That's a hypothesis, not a result.",
      "on_screen": "Simple diagram: tryptophan splitting into two arrows, one to serotonin, one to the kynurenine pathway. Stamp across it: 'PROPOSED - NOT TESTED'.",
      "claim_refs": [
        "Abstract: 'We propose that elevated peripheral IL-6 reduces central serotonin availability by shunting tryptophan into the kynurenine pathway'",
        "Study design: proposed, untested mechanism"
      ]
    },
    {
      "beat": "What this can't say yet",
      "narration": "The study never measured those chemicals, and never changed anyone's IL-6. IL-6 was also measured only once, at the start, so a single baseline measurement is all we have. It's an observation, so it can't show cause and effect, and inflammation may simply travel alongside the real culprit.",
      "on_screen": "Checklist: 'Kynurenine metabolites measured: none', 'IL-6 not manipulated', 'Observational cohort', 'Single baseline measurement'.",
      "claim_refs": [
        "Results: kynurenine metabolites measured: none",
        "Methods: no metabolite panel was run; IL-6 was not manipulated",
        "Limitations: observational cohort; single baseline IL-6 measurement"
      ]
    },
    {
      "beat": "Bottom line",
      "narration": "So: a common blood marker lines up with who does worse on an SSRI. That's a promising lead for matching patients to treatments, but the explanation behind it still needs testing.",
      "on_screen": "Closing card: 'Association: yes. Explanation: still a hypothesis.'",
      "claim_refs": [
        "Conclusion: higher baseline IL-6 associated with lower SSRI response; kynurenine account proposed",
        "Discussion: candidate stratification marker"
      ]
    }
  ]
}
